using System;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
namespace FileCompass {
 internal static class SettingsUx {
  internal static DockPanel Frame(Window window,string title,out StackPanel actions){
   Install(window);var root=new DockPanel();CopyUi.Surface(window,root);((Border)((Grid)window.Content).Children[0]).Padding=new Thickness(0);
   var header=new Border{Background=CompactTheme.PanelSurface,BorderBrush=CompactTheme.Line,BorderThickness=new Thickness(0,0,0,1),CornerRadius=new CornerRadius(8,8,0,0),Padding=new Thickness(20,15,20,15),Child=new TextBlock{Text=title,FontSize=20,FontWeight=FontWeights.SemiBold,TextWrapping=TextWrapping.Wrap}};DockPanel.SetDock(header,Dock.Top);root.Children.Add(header);
   actions=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};var footer=new Border{Child=actions,Background=CompactTheme.PanelSurface,BorderBrush=CompactTheme.Line,BorderThickness=new Thickness(0,1,0,0),Padding=new Thickness(14,12,14,12),CornerRadius=new CornerRadius(0,0,8,8)};DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);footer.Loaded+=delegate{footer.Visibility=((Panel)footer.Child).Children.Count==0?Visibility.Collapsed:Visibility.Visible;};return root;
  }
  internal static string Prompt(Window owner,string title,string value,string description=null,string acceptKey="action.save"){var window=new Window();CopyUi.Style(window,owner,title,460);StackPanel actions;var root=Frame(window,title,out actions);if(!String.IsNullOrEmpty(description)){var help=new TextBlock{Text=description,TextWrapping=TextWrapping.Wrap,Foreground=FluentTheme.Muted,Margin=new Thickness(20,16,20,0)};DockPanel.SetDock(help,Dock.Top);root.Children.Add(help);}var input=new TextBox{Text=value??"",MinHeight=32,VerticalContentAlignment=VerticalAlignment.Center,Margin=new Thickness(20,18,20,18)};root.Children.Add(input);var cancel=CopyUi.Button(L.Text("action.cancel"),delegate{window.DialogResult=false;});cancel.IsCancel=true;actions.Children.Add(cancel);var save=CopyUi.Button(L.Text(acceptKey),delegate{window.DialogResult=true;});save.IsDefault=true;FluentTheme.Primary(save);actions.Children.Add(save);window.Loaded+=delegate{input.Focus();input.SelectAll();};return window.ShowDialog()==true?input.Text:null;}
  internal static void Install(Window window){
   var group=new Style(typeof(GroupBox),window.TryFindResource(typeof(GroupBox)) as Style);group.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(12)));group.Setters.Add(new Setter(Control.BackgroundProperty,CompactTheme.PanelSurface));group.Setters.Add(new Setter(Control.TemplateProperty,(ControlTemplate)XamlReader.Parse(@"<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' TargetType='GroupBox'><Border Background='{TemplateBinding Background}' BorderBrush='{StaticResource CompassLine}' BorderThickness='1' CornerRadius='6' Padding='{TemplateBinding Padding}'><DockPanel><ContentPresenter DockPanel.Dock='Top' ContentSource='Header' Margin='0,0,0,9' TextElement.FontWeight='SemiBold' TextElement.Foreground='{StaticResource CompassText}'/><ContentPresenter ContentSource='Content'/></DockPanel></Border></ControlTemplate>")));window.Resources[typeof(GroupBox)]=group;
  }
  internal static void Navigation(ListBox list){
   list.Background=CompactTheme.PanelSurface;list.BorderThickness=new Thickness(0);list.HorizontalContentAlignment=HorizontalAlignment.Stretch;
   var style=new Style(typeof(ListBoxItem));style.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(10,9,10,9)));style.Setters.Add(new Setter(FrameworkElement.MarginProperty,new Thickness(0,2,0,2)));style.Setters.Add(new Setter(Control.TemplateProperty,(ControlTemplate)XamlReader.Parse(@"<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' TargetType='ListBoxItem'><Border Background='{TemplateBinding Background}' Padding='{TemplateBinding Padding}' CornerRadius='4'><ContentPresenter/></Border></ControlTemplate>")));var selected=new Trigger{Property=ListBoxItem.IsSelectedProperty,Value=true};selected.Setters.Add(new Setter(Control.BackgroundProperty,CompactTheme.ActivePath));selected.Setters.Add(new Setter(Control.ForegroundProperty,FluentTheme.Accent));selected.Setters.Add(new Setter(Control.FontWeightProperty,FontWeights.SemiBold));style.Triggers.Add(selected);list.ItemContainerStyle=style;
   var text=new FrameworkElementFactory(typeof(TextBlock));text.SetBinding(TextBlock.TextProperty,new System.Windows.Data.Binding());text.SetValue(TextBlock.TextWrappingProperty,TextWrapping.Wrap);list.ItemTemplate=new DataTemplate{VisualTree=text};
  }
 }
}
